import re
from fractions import Fraction


def fraction_expr(s: str) -> str:
    token_re = re.compile(r"\d+/\d+|\d+|[()+*-]")
    tokens = []
    pos = 0

    while pos < len(s):
        if s[pos].isspace():
            pos += 1
            continue
        match = token_re.match(s, pos)
        if not match:
            raise ValueError("malformed input")
        tokens.append(match.group())
        pos = match.end()

    if not tokens:
        raise ValueError("empty expression")

    index = 0

    def peek():
        return tokens[index] if index < len(tokens) else None

    def consume(expected=None):
        nonlocal index
        token = peek()
        if token is None or (expected is not None and token != expected):
            raise ValueError("malformed input")
        index += 1
        return token

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            operator = consume()
            rhs = parse_term()
            value = value + rhs if operator == "+" else value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() == "*":
            consume("*")
            value *= parse_factor()
        return value

    def parse_factor():
        if peek() == "-":
            consume("-")
            return -parse_factor()
        if peek() == "(":
            consume("(")
            value = parse_expr()
            consume(")")
            return value

        token = peek()
        if token is None or not (token.isdigit() or re.fullmatch(r"\d+/\d+", token)):
            raise ValueError("malformed input")
        consume()
        try:
            if "/" in token:
                numerator, denominator = token.split("/")
                return Fraction(int(numerator), int(denominator))
            return Fraction(int(token))
        except (ValueError, ZeroDivisionError) as exc:
            raise ValueError("invalid fraction") from exc

    try:
        result = parse_expr()
        if index != len(tokens):
            raise ValueError("unexpected token")
    except ZeroDivisionError as exc:
        raise ValueError("zero denominator") from exc

    if result.numerator == 0:
        return '0'
    return str(result.numerator) if result.denominator == 1 else f"{result.numerator}/{result.denominator}"
